<script setup>
import {computed,onMounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api} from '../api'
import {questionStages,formatDate} from '../utils/assignments'
import StudioFeedback from '../components/StudioFeedback.vue'
const route=useRoute(),router=useRouter(),courses=ref([]),course=ref(''),students=ref([]),person=ref(null),statistics=ref(null),busy=ref(false),error=ref(''),search=ref('')
const mode=computed(()=>route.meta.studioMode || 'students')
const filtered=computed(()=>students.value.filter(s=>`${s.displayName} ${s.studentNumber||''}`.includes(search.value)))
const labels={students:'學生清單',history:'個別學生學習歷程',statistics:'全班統計',export:'匯出'}
async function load(){busy.value=true;error.value='';try{courses.value=await api('/studio/teaching/courses');course.value=route.query.course || courses.value[0]?.id || '';if(!course.value)return;const base=`/studio/teaching/courses/${course.value}`;if(mode.value==='students')students.value=await api(base+'/students');if(mode.value==='history')person.value=await api(base+'/students/'+route.params.studentId);if(mode.value==='statistics')statistics.value=await api(base+'/statistics')}catch(e){error.value=e.message}finally{busy.value=false}}
async function change(){await router.replace({path:mode.value==='history'?'/teaching':route.path,query:{course:course.value}});await load()}
async function download(){busy.value=true;error.value='';try{const blob=await api(`/studio/teaching/courses/${course.value}/export`,{method:'POST',download:true});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='案例學習歷程.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=e.message}finally{busy.value=false}}
function stageLabel(stage){return questionStages.find(s=>s.key===stage)?.label || stage}
onMounted(load)
</script>
<template><section class="page-heading"><div><p class="eyebrow">{{{students:'T1',history:'T2',statistics:'T3',export:'T4'}[mode]}} · TEACHING</p><h1>{{labels[mode]}}</h1><p class="muted">僅檢視所屬課程學生正式提交的作答與對應文字回饋；私人草稿不提供教學端讀取。</p></div></section><p v-if="error" class="error-box" role="alert">{{error}}</p><label v-if="courses.length">課程<select aria-label="教學課程" v-model="course" @change="change"><option v-for="c in courses" :key="c.id" :value="c.id">{{c.code}} · {{c.title}}</option></select></label><RouterLink v-if="course" :to="`/courses/${course}?section=students`" class="back-link">← 返回所選課程</RouterLink><nav class="course-navigation" aria-label="教師端功能"><RouterLink :to="{path:'/teaching',query:{course}}">學生清單</RouterLink><RouterLink :to="{path:'/teaching/statistics',query:{course}}">全班統計</RouterLink><RouterLink :to="{path:'/teaching/export',query:{course}}">匯出</RouterLink></nav><p v-if="!busy && !courses.length" class="surface form-surface">目前沒有具教師／助教資格的課程。請由管理者建立課程或加入課程成員。</p><section v-if="mode==='students' && course" class="surface form-surface"><div class="section-title"><h2>課程學生</h2><label>搜尋學生<input v-model="search" placeholder="姓名或學號" /></label></div><div class="table-scroll"><table class="data-table"><thead><tr><th>學號</th><th>姓名</th><th>正式提交次數</th><th>最近提交</th><th>學習歷程</th></tr></thead><tbody><tr v-for="s in filtered" :key="s.id"><td>{{s.studentNumber || '未填學號'}}</td><td>{{s.displayName}}</td><td>{{s.submittedCount}}</td><td>{{formatDate(s.lastSubmittedAt)}}</td><td><RouterLink :to="{path:`/teaching/students/${s.id}`,query:{course}}" class="text-button">查看學習歷程</RouterLink></td></tr></tbody></table></div><p v-if="!filtered.length" class="empty-inline">目前沒有符合條件的學生。</p></section><template v-if="mode==='history' && person"><h2>{{person.student.displayName}} · {{person.student.studentNumber}}</h2><p v-if="!person.records.length" class="surface form-surface">尚無正式提交紀錄。未提交草稿維持私人。</p><section v-for="record in person.records" :key="record.attempt.id" class="surface form-surface"><h2>{{record.caseDetail.title}} · 案例 v{{record.caseDetail.versionNo}}</h2><p class="muted">{{formatDate(record.attempt.submittedAt)}}</p><details><summary>案例原文</summary><p class="studio-prose">{{record.caseDetail.material}}</p></details><article v-for="answer in record.attempt.answers" :key="answer.id" class="question-editor"><h3>{{stageLabel(answer.stage)}} · 正式提交版本 {{answer.revisionNo}}</h3><p class="studio-prose">{{answer.text}}</p><StudioFeedback v-if="record.attempt.feedback.some(f=>f.answerVersionId===answer.id)" read-only :feedback="record.attempt.feedback.find(f=>f.answerVersionId===answer.id)" /><p v-else class="muted">此提交版本沒有對應的 AI 回饋。</p></article></section></template><section v-if="mode==='statistics' && statistics" class="surface form-surface"><h2>正式提交概況</h2><div class="gradebook-summary"><div><span>有效學生</span><strong>{{statistics.studentCount}}</strong></div><div><span>已發布案例</span><strong>{{statistics.caseCount}}</strong></div><div><span>已提交學生</span><strong>{{statistics.submittedStudents}}</strong></div><div><span>正式提交紀錄</span><strong>{{statistics.submittedAttempts}}</strong></div></div><p class="field-hint">只有正式提交納入統計，練習與私人草稿不計入。文字回饋不換算分數或品質排名。</p><div class="table-scroll"><table class="data-table"><thead><tr><th>分析階段</th><th>正式作答</th><th>有完成文字回饋</th></tr></thead><tbody><tr v-for="s in statistics.stages" :key="s.stage"><td>{{stageLabel(s.stage)}}</td><td>{{s.submittedAnswers}}</td><td>{{s.completedFeedback}}</td></tr></tbody></table></div></section><section v-if="mode==='export' && course" class="surface form-surface"><h2>匯出正式學習歷程</h2><p>CSV 包含所選課程的學號、姓名、案例版本、階段、提交時間、正式作答及對應 AI 文字回饋。私人草稿與其他課程資料不匯出。</p><p class="field-hint">下載包含學生學習資料，請依課程資料管理規則保存；每次下載會留下稽核紀錄。</p><button class="button primary" :disabled="busy" @click="download">下載 CSV</button></section></template>
